{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "name": "Execution Desk Data",
    "url": "http://localhost:7806",
    "widgets_json": {
      "live_orders_grid": {
        "name": "Live Orders Grid",
        "description": "Streaming order blotter over websocket.",
        "endpoint": "/live-orders",
        "type": "live_grid",
        "gridData": {
          "w": 24,
          "h": 12
        },
        "wsEndpoint": "live-orders-ws",
        "data": {
          "wsRowIdColumn": "order_id",
          "table": {
            "columnsDefs": [
              {
                "field": "order_id",
                "headerName": "Order",
                "cellDataType": "text"
              },
              {
                "field": "px",
                "headerName": "Price",
                "cellDataType": "number",
                "renderFn": "showCellChange",
                "renderFnParams": {
                  "colorValueKey": "px_change"
                }
              }
            ]
          }
        }
      }
    },
    "apps_json": [
      {
        "name": "Live Order Tape",
        "description": "Streaming orders for the execution desk.",
        "tabs": {
          "orders": {
            "id": "orders",
            "name": "Orders",
            "layout": [
              {
                "i": "live_orders_grid",
                "x": 0,
                "y": 0,
                "w": 24,
                "h": 12
              }
            ]
          }
        }
      }
    ]
  }
}
